CREATE OR REPLACE FUNCTION public.assign_fiscal_documents_to_load(_tenant_id uuid, _load_id uuid, _document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int := 0;
  v_requested int := 0;
  v_blocked int := 0;
  v_doc_ids uuid[];
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF _load_id IS NULL OR _document_ids IS NULL OR array_length(_document_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'invalid_input';
  END IF;

  SELECT array_agg(DISTINCT d.id)
    INTO v_doc_ids
  FROM unnest(_document_ids) AS d(id)
  WHERE d.id IS NOT NULL;

  IF v_doc_ids IS NULL OR array_length(v_doc_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'invalid_input';
  END IF;

  IF public._load_is_locked(_load_id) THEN
    RAISE EXCEPTION 'load_locked';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.loads l
    WHERE l.id = _load_id
      AND l.tenant_id = _tenant_id
  ) THEN
    RAISE EXCEPTION 'load_not_found';
  END IF;

  SELECT count(*)::int
    INTO v_requested
  FROM unnest(v_doc_ids) AS d(id);

  SELECT count(*)::int
    INTO v_blocked
  FROM public.fiscal_documents fd
  WHERE fd.id = ANY(v_doc_ids)
    AND fd.tenant_id = _tenant_id
    AND fd.load_id IS NOT NULL
    AND fd.load_id <> _load_id;

  IF v_blocked > 0 THEN
    RAISE EXCEPTION 'document_already_linked';
  END IF;

  UPDATE public.fiscal_documents
    SET load_id = _load_id,
        updated_at = now()
    WHERE id = ANY(v_doc_ids)
      AND tenant_id = _tenant_id
      AND (load_id IS NULL OR load_id = _load_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count <> v_requested THEN
    RAISE EXCEPTION 'document_link_count_mismatch: expected %, updated %', v_requested, v_count;
  END IF;

  INSERT INTO public.load_items (
    tenant_id,
    load_id,
    fiscal_document_id,
    item_description,
    pallet_count,
    weight_kg,
    volume_m3
  )
  SELECT _tenant_id,
         _load_id,
         fd.id,
         COALESCE(NULLIF(fd.product_summary, ''), 'Documento ' || COALESCE(fd.invoice_number, fd.id::text)),
         COALESCE(fd.pallet_count, 0),
         COALESCE(fd.weight_kg, 0),
         0
  FROM public.fiscal_documents fd
  WHERE fd.id = ANY(v_doc_ids)
    AND fd.tenant_id = _tenant_id
    AND fd.load_id = _load_id
    AND NOT EXISTS (
      SELECT 1
      FROM public.load_items li
      WHERE li.fiscal_document_id = fd.id
        AND li.load_id = _load_id
    );

  PERFORM public._log_entity_audit(
    _tenant_id,
    'load',
    _load_id,
    'assign_documents',
    NULL,
    jsonb_build_object('document_ids', to_jsonb(v_doc_ids), 'updated', v_count),
    'composition_rpc'
  );

  RETURN jsonb_build_object('updated', v_count, 'load_id', _load_id);
END $function$

CREATE OR REPLACE FUNCTION public.assign_fiscal_documents_to_load_v2(_tenant_id uuid, _load_id uuid, _document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb;
BEGIN
  v_result := public.assign_fiscal_documents_to_load(_tenant_id, _load_id, _document_ids);
  PERFORM public.recalculate_load_totals(_tenant_id, _load_id);
  RETURN v_result || jsonb_build_object('totals_recalculated', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_load_item_v3(p_tenant_id uuid, p_item_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_load_id uuid;
  v_fiscal_document_id uuid;
  v_old jsonb;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  SELECT li.load_id, li.fiscal_document_id, to_jsonb(li)
    INTO v_load_id, v_fiscal_document_id, v_old
  FROM public.load_items li
  WHERE li.id = p_item_id AND li.tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN RETURN false; END IF;
  IF public._load_is_locked(v_load_id) THEN RAISE EXCEPTION 'load_locked'; END IF;

  DELETE FROM public.load_items
  WHERE id = p_item_id AND tenant_id = p_tenant_id;

  IF v_fiscal_document_id IS NOT NULL THEN
    UPDATE public.fiscal_documents
    SET load_id = NULL, updated_at = now()
    WHERE id = v_fiscal_document_id
      AND tenant_id = p_tenant_id
      AND load_id = v_load_id;
  END IF;

  PERFORM public.recalculate_load_totals(p_tenant_id, v_load_id);
  PERFORM public._log_entity_audit(
    p_tenant_id,
    'load_item',
    p_item_id,
    'delete',
    v_old,
    NULL,
    'delete_load_item_v3'
  );
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.move_load_items_between_loads(_tenant_id uuid, _source_load_id uuid, _target_load_id uuid, _item_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_moved int; v_doc_ids uuid[];
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF _source_load_id = _target_load_id THEN RAISE EXCEPTION 'same_load'; END IF;
  IF public._load_is_locked(_source_load_id) THEN RAISE EXCEPTION 'source_load_locked'; END IF;
  IF public._load_is_locked(_target_load_id) THEN RAISE EXCEPTION 'target_load_locked'; END IF;

  SELECT COALESCE(array_agg(DISTINCT fiscal_document_id) FILTER (WHERE fiscal_document_id IS NOT NULL),
                  ARRAY[]::uuid[])
    INTO v_doc_ids
  FROM public.load_items
  WHERE id = ANY(_item_ids) AND load_id = _source_load_id AND tenant_id = _tenant_id;

  UPDATE public.load_items
    SET load_id = _target_load_id, updated_at = now()
    WHERE id = ANY(_item_ids) AND load_id = _source_load_id AND tenant_id = _tenant_id;
  GET DIAGNOSTICS v_moved = ROW_COUNT;

  IF array_length(v_doc_ids, 1) IS NOT NULL THEN
    UPDATE public.fiscal_documents
      SET load_id = _target_load_id, updated_at = now()
      WHERE id = ANY(v_doc_ids) AND tenant_id = _tenant_id;
  END IF;

  PERFORM public._log_entity_audit(_tenant_id, 'load', _source_load_id, 'move_items_out',
    NULL, jsonb_build_object('target_load_id', _target_load_id, 'item_ids', to_jsonb(_item_ids),
                             'document_ids', to_jsonb(v_doc_ids)), 'composition_rpc');
  PERFORM public._log_entity_audit(_tenant_id, 'load', _target_load_id, 'move_items_in',
    NULL, jsonb_build_object('source_load_id', _source_load_id, 'item_ids', to_jsonb(_item_ids),
                             'document_ids', to_jsonb(v_doc_ids)), 'composition_rpc');

  RETURN jsonb_build_object('moved', v_moved, 'document_ids', COALESCE(to_jsonb(v_doc_ids), '[]'::jsonb));
END $function$

CREATE OR REPLACE FUNCTION public.remove_fiscal_documents_from_load(_tenant_id uuid, _load_id uuid, _document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count int;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF public._load_is_locked(_load_id) THEN RAISE EXCEPTION 'load_locked'; END IF;

  DELETE FROM public.load_items
    WHERE load_id = _load_id AND fiscal_document_id = ANY(_document_ids) AND tenant_id = _tenant_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  UPDATE public.fiscal_documents
    SET load_id = NULL, updated_at = now()
    WHERE id = ANY(_document_ids) AND tenant_id = _tenant_id AND load_id = _load_id;

  PERFORM public._log_entity_audit(_tenant_id, 'load', _load_id, 'remove_documents',
    NULL, jsonb_build_object('document_ids', to_jsonb(_document_ids)), 'composition_rpc');

  RETURN jsonb_build_object('removed', v_count, 'load_id', _load_id);
END $function$

CREATE OR REPLACE FUNCTION public.remove_fiscal_documents_from_load_v2(_tenant_id uuid, _load_id uuid, _document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb;
BEGIN
  v_result := public.remove_fiscal_documents_from_load(_tenant_id, _load_id, _document_ids);
  PERFORM public.recalculate_load_totals(_tenant_id, _load_id);
  RETURN v_result || jsonb_build_object('totals_recalculated', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.upsert_load_item_v3(p_tenant_id uuid, p_load_id uuid DEFAULT NULL::uuid, p_item_id uuid DEFAULT NULL::uuid, p_order_id uuid DEFAULT NULL::uuid, p_item_description text DEFAULT NULL::text, p_quantity numeric DEFAULT NULL::numeric, p_pallet_count numeric DEFAULT NULL::numeric, p_weight_kg numeric DEFAULT NULL::numeric, p_volume_m3 numeric DEFAULT NULL::numeric, p_status text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_fiscal_document_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item public.load_items;
  v_item_id uuid;
  v_load_id uuid;
  v_fiscal_document_id uuid;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(p_tenant_id) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF p_item_id IS NOT NULL THEN
    SELECT * INTO v_item
    FROM public.load_items
    WHERE id = p_item_id AND tenant_id = p_tenant_id
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'load_item_not_found'; END IF;
    IF p_load_id IS NOT NULL AND p_load_id <> v_item.load_id THEN
      RAISE EXCEPTION 'load_change_requires_move_rpc';
    END IF;
    v_load_id := v_item.load_id;
  ELSE
    v_load_id := p_load_id;
  END IF;

  IF v_load_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.loads WHERE id = v_load_id AND tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'load_not_found';
  END IF;
  IF public._load_is_locked(v_load_id) THEN RAISE EXCEPTION 'load_locked'; END IF;

  IF p_order_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.orders WHERE id = p_order_id AND tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'order_not_found';
  END IF;
  IF p_fiscal_document_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.fiscal_documents WHERE id = p_fiscal_document_id AND tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'fiscal_document_not_found';
  END IF;
  IF p_status IS NOT NULL AND p_status <> ALL(ARRAY[
    'pending', 'waiting_conference', 'in_stock', 'picking', 'ready_for_load',
    'in_loading', 'loaded', 'in_transit', 'delivered', 'divergence', 'return', 'redelivery'
  ]) THEN
    RAISE EXCEPTION 'invalid_load_item_status';
  END IF;

  IF p_item_id IS NULL THEN
    INSERT INTO public.load_items (
      tenant_id, load_id, order_id, fiscal_document_id, item_description,
      quantity, pallet_count, weight_kg, volume_m3, status, notes
    ) VALUES (
      p_tenant_id, v_load_id, p_order_id, p_fiscal_document_id,
      COALESCE(p_item_description, ''), COALESCE(p_quantity, 0),
      COALESCE(p_pallet_count, 0), COALESCE(p_weight_kg, 0), COALESCE(p_volume_m3, 0),
      COALESCE(p_status, 'pending'), p_notes
    ) RETURNING id, fiscal_document_id INTO v_item_id, v_fiscal_document_id;
  ELSE
    UPDATE public.load_items
    SET order_id = COALESCE(p_order_id, order_id),
        item_description = COALESCE(p_item_description, item_description),
        quantity = COALESCE(p_quantity, quantity),
        pallet_count = COALESCE(p_pallet_count, pallet_count),
        weight_kg = COALESCE(p_weight_kg, weight_kg),
        volume_m3 = COALESCE(p_volume_m3, volume_m3),
        status = COALESCE(p_status, status),
        notes = COALESCE(p_notes, notes),
        fiscal_document_id = COALESCE(p_fiscal_document_id, fiscal_document_id),
        updated_at = now()
    WHERE id = p_item_id AND tenant_id = p_tenant_id
    RETURNING id, fiscal_document_id INTO v_item_id, v_fiscal_document_id;
  END IF;

  IF v_fiscal_document_id IS NOT NULL THEN
    UPDATE public.fiscal_documents
    SET load_id = v_load_id, updated_at = now()
    WHERE id = v_fiscal_document_id AND tenant_id = p_tenant_id;
  END IF;

  PERFORM public.recalculate_load_totals(p_tenant_id, v_load_id);
  PERFORM public._log_entity_audit(
    p_tenant_id,
    'load_item',
    v_item_id,
    CASE WHEN p_item_id IS NULL THEN 'create' ELSE 'update' END,
    NULL,
    jsonb_build_object('load_id', v_load_id, 'status', COALESCE(p_status, v_item.status, 'pending')),
    'upsert_load_item_v3'
  );

  RETURN v_item_id;
END;
$function$

CREATE OR REPLACE FUNCTION public._sync_fiscal_document_load_mirror()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_document_id uuid;
  v_load_count integer;
  v_load_id uuid;
BEGIN
  FOR v_document_id IN
    SELECT DISTINCT document_id
    FROM unnest(ARRAY[
      CASE WHEN TG_OP <> 'DELETE' THEN NEW.fiscal_document_id ELSE NULL END,
      CASE WHEN TG_OP <> 'INSERT' THEN OLD.fiscal_document_id ELSE NULL END
    ]) AS affected(document_id)
    WHERE document_id IS NOT NULL
  LOOP
    SELECT count(DISTINCT load_id), (array_agg(DISTINCT load_id ORDER BY load_id))[1]
    INTO v_load_count, v_load_id
    FROM public.load_items
    WHERE fiscal_document_id = v_document_id;

    IF v_load_count > 1 THEN
      RAISE EXCEPTION 'Documento fiscal % não pode pertencer a mais de uma carga', v_document_id;
    END IF;

    UPDATE public.fiscal_documents
    SET load_id = v_load_id,
        updated_at = now()
    WHERE id = v_document_id
      AND load_id IS DISTINCT FROM v_load_id;
  END LOOP;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_handle_empty_load_on_doc_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    -- If it's an UPDATE that changed load_id, check the OLD load_id
    IF TG_OP = 'UPDATE' THEN
        IF OLD.load_id IS NOT NULL AND (NEW.load_id IS NULL OR NEW.load_id <> OLD.load_id OR NEW.status = 'deleted') THEN
            PERFORM public.delete_load_if_empty(OLD.load_id);
        END IF;
    -- If it's a DELETE, check the OLD load_id
    ELSIF TG_OP = 'DELETE' THEN
        IF OLD.load_id IS NOT NULL THEN
            PERFORM public.delete_load_if_empty(OLD.load_id);
        END IF;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_load_if_empty(v_load_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_doc_count INT;
    v_tenant_id UUID;
BEGIN
    IF v_load_id IS NULL THEN
        RETURN;
    END IF;

    -- Count active fiscal documents for this load
    SELECT count(*) INTO v_doc_count
    FROM public.fiscal_documents
    WHERE load_id = v_load_id 
      AND deleted_at IS NULL 
      AND status <> 'deleted';

    IF v_doc_count = 0 THEN
        SELECT tenant_id INTO v_tenant_id FROM public.loads WHERE id = v_load_id;

        IF v_tenant_id IS NOT NULL THEN
            -- delete_load_safely handles unlinking remaining items and deleting the load
            PERFORM public.delete_load_safely(v_tenant_id, v_load_id);
        END IF;
    END IF;
EXCEPTION WHEN OTHERS THEN
    NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_load_safely(_tenant_id uuid, _load_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_pod int; v_terminal_doc int; v_dtl int; v_crit_occ int;
BEGIN
  IF NOT public.is_tenant_operator_or_admin(_tenant_id) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF public._load_is_locked(_load_id) THEN RAISE EXCEPTION 'load_locked'; END IF;

  SELECT count(*) INTO v_pod FROM public.proof_of_delivery WHERE load_id = _load_id;
  IF v_pod > 0 THEN RAISE EXCEPTION 'load_has_pod'; END IF;

  SELECT count(*) INTO v_terminal_doc
    FROM public.fiscal_documents
    WHERE load_id = _load_id AND tenant_id = _tenant_id
      AND status IN ('delivered','partial_delivery','returned','refused','failed','not_delivered');
  IF v_terminal_doc > 0 THEN RAISE EXCEPTION 'load_has_terminal_documents'; END IF;

  SELECT count(*) INTO v_dtl FROM public.dispatch_trip_loads WHERE load_id = _load_id;
  IF v_dtl > 0 THEN RAISE EXCEPTION 'load_in_dispatch_trip'; END IF;

  SELECT count(*) INTO v_crit_occ
    FROM public.operational_events
    WHERE load_id = _load_id AND public_status = 'open' AND severity IN ('high','critical');
  IF v_crit_occ > 0 THEN RAISE EXCEPTION 'load_has_critical_occurrence'; END IF;

  UPDATE public.fiscal_documents SET load_id = NULL, updated_at = now()
    WHERE load_id = _load_id AND tenant_id = _tenant_id;
  DELETE FROM public.load_items WHERE load_id = _load_id AND tenant_id = _tenant_id;
  DELETE FROM public.loads WHERE id = _load_id AND tenant_id = _tenant_id;

  PERFORM public._log_entity_audit(_tenant_id, 'load', _load_id, 'delete_safely', NULL, NULL, 'composition_rpc');

  RETURN jsonb_build_object('deleted', true, 'load_id', _load_id);
END $function$
